<?php namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Services\ItineraryPlannerService; use Illuminate\Http\Request; class PlannerController extends Controller { public function preview(Request $r,ItineraryPlannerService $s){$d=$r->validate(['place_ids'=>'required|array|min:1','place_ids.*'=>'integer|exists:places,id','start_latitude'=>'required|numeric|between:-90,90','start_longitude'=>'required|numeric|between:-180,180','start_time'=>'required|date_format:H:i','end_time'=>'required|date_format:H:i']);return ['data'=>$s->preview($d)];} }
